-- Replace the legacy fixed-title daily notifications with the new feature-led copy.
-- Keep the same message IDs and schedule; refresh atomically to avoid the unique-body constraint.
-- All 100 headlines and bodies are distinct. The temporary body values are never committed.
BEGIN;
UPDATE public.engagement_messages SET body='engagement-refresh-in-progress:' || id WHERE id BETWEEN 'tip-001' AND 'tip-100';
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, body=EXCLUDED.body;
COMMIT;
